diff --git a/repro60573/check.js b/repro60573/check.js
new file mode 100644
index 000000000..01600df74
--- /dev/null
+++ b/repro60573/check.js
@@ -0,0 +1,36 @@
+// Usage (from repo root): node repro60573/check.js [path-to-typescript.js] [file.ts]
+// Exits non-zero if the printed type of `Test` is not `{ prop1: "hello"; }`.
+const path = require("path");
+const fs = require("fs");
+const tsPath = path.resolve(process.argv[2] || path.join(__dirname, "../built/local/typescript.js"));
+const file = path.resolve(process.argv[3] || path.join(__dirname, "repro.ts"));
+const ts = require(tsPath);
+const expected = '{ prop1: "hello"; }';
+
+const options = { strict: true, noEmit: true, target: ts.ScriptTarget.ES2022, types: [], lib: ["lib.es2022.d.ts"] };
+const program = ts.createProgram([file], options);
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+let alias;
+ts.forEachChild(sf, n => { if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") alias = n; });
+const printed = checker.typeToString(checker.getTypeAtLocation(alias.name), undefined, ts.TypeFormatFlags.NoTruncation);
+
+// Hover text as shown by the playground / editors.
+const host = {
+    getScriptFileNames: () => [file], getScriptVersion: () => "1",
+    getScriptSnapshot: f => fs.existsSync(f) ? ts.ScriptSnapshot.fromString(fs.readFileSync(f, "utf8")) : undefined,
+    getCurrentDirectory: () => process.cwd(), getCompilationSettings: () => options,
+    getDefaultLibFileName: o => ts.getDefaultLibFilePath(o),
+    fileExists: ts.sys.fileExists, readFile: ts.sys.readFile, readDirectory: ts.sys.readDirectory,
+};
+const ls = ts.createLanguageService(host);
+const hover = ts.displayPartsToString(ls.getQuickInfoAtPosition(file, alias.name.getStart()).displayParts).replace(/\s+/g, " ");
+const expectedHover = 'type Test = { prop1: "hello"; }';
+
+console.log(`typescript ${ts.version}`);
+console.log(`typeToString(Test): ${printed}`);
+console.log(`quickinfo:          ${hover}`);
+let ok = true;
+if (printed !== expected) { console.error(`FAIL: expected typeToString(Test) to be ${expected}`); ok = false; }
+if (hover !== expectedHover) { console.error(`FAIL: expected hover to be ${expectedHover}`); ok = false; }
+process.exit(ok ? 0 : 1);
diff --git a/repro60573/repro.ts b/repro60573/repro.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro60573/repro.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
diff --git a/repro60573/repro_separate_line.ts b/repro60573/repro_separate_line.ts
new file mode 100644
index 000000000..b0bfde57e
--- /dev/null
+++ b/repro60573/repro_separate_line.ts
@@ -0,0 +1,24 @@
+// Variant from the report: the assertion on its own line. Prints correctly on 5.7 too.
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const strWrapper = stringWrapper() as Wrapper<"hello">;
+
+const value = objWrapper({
+    prop1: strWrapper
+});
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
